insert into public.documents (id, document_name, document_number, standardization_number, issuing_unit, established_date, effective_date, status, purpose, scope, attachment_information) values ('doc-st-002', 'Standardisasi Teknologi Informasi', 'Standardisasi Teknologi Informasi', 'ST-002/SJ.7/KITG/07/2024-01', 'Kementerian Komunikasi dan Digital - Sekretariat Jenderal', '2025-10-03', '2025-10-03', 'Berlaku', 'Standardisasi Teknologi Informasi (TI) ini disusun sebagai acuan dalam perencanaan, implementasi, dan pengelolaan perangkat serta layanan TI. Standardisasi ini tidak dimaksudkan untuk membatasi penggunaan teknologi, melainkan memastikan pemanfaatan TI tetap terarah, seragam, dan sesuai kebutuhan organisasi.', 'Infrastruktur TI; sistem informasi/aplikasi; data dan informasi; keamanan informasi/siber; serta kompetensi sumber daya manusia yang menggunakannya.', 'Tidak ada.') on conflict (id) do update set document_name=excluded.document_name, standardization_number=excluded.standardization_number, issuing_unit=excluded.issuing_unit, status=excluded.status, purpose=excluded.purpose, scope=excluded.scope, attachment_information=excluded.attachment_information;
insert into public.document_sections (id, document_id, section_number, title, content, sort_order) values ('section-1-1', 'doc-st-002', '1.1', 'Latar Belakang', 'Perkembangan teknologi informasi yang cepat mendorong organisasi untuk terus beradaptasi dengan inovasi digital. Hal ini membuka peluang besar untuk meningkatkan produktivitas, transparansi, dan kualitas layanan. Namun, bersamaan dengan itu juga muncul tantangan seperti interoperabilitas sistem, keamanan data, serta kesiapan sumber daya manusia dalam menghadapi perubahan teknologi. Perbedaan cara penggunaan dan ketiadaan panduan yang seragam sering kali membuat layanan TI sulit diintegrasikan secara menyeluruh, bahkan berisiko menimbulkan masalah baru. Tanpa standar yang jelas, implementasi TI bisa berjalan tidak konsisten dan tidak terarah, menimbulkan duplikasi, serta menghambat kolaborasi antar unit kerja dan pencapaian tujuan organisasi. Untuk itu, dibutuhkan standardisasi TI yang menjadi pedoman bersama dalam perencanaan, pengembangan, dan penerapan teknologi agar setiap sistem saling terhubung, aman, efisien, dan konsisten.', 1) on conflict (id) do update set title=excluded.title, content=excluded.content, sort_order=excluded.sort_order;
insert into public.document_sections (id, document_id, section_number, title, content, sort_order) values ('section-1-2', 'doc-st-002', '1.2', 'Maksud dan Tujuan', 'Maksud: menjadi acuan dalam perencanaan, implementasi, dan pengelolaan perangkat serta layanan TI tanpa membatasi penggunaan teknologi. Tujuan: agar pengelolaan TI berjalan efektif, efisien, aman, dan konsisten melalui pedoman yang jelas mengenai teknologi yang harus disediakan, digunakan, dan dimiliki.', 2) on conflict (id) do update set title=excluded.title, content=excluded.content, sort_order=excluded.sort_order;
insert into public.document_sections (id, document_id, section_number, title, content, sort_order) values ('section-1-3', 'doc-st-002', '1.3', 'Manfaat', '1) Menyediakan panduan yang jelas dalam perencanaan, pengembangan, implementasi, dan pemeliharaan layanan TI. 2) Menciptakan keseragaman standar TI untuk mengurangi kompleksitas, meningkatkan konsistensi, dan mempermudah manajemen TI. 3) Memastikan produk dan layanan TI memenuhi standar tertentu sehingga memiliki kualitas yang konsisten, andal, dan mudah dikendalikan. 4) Melindungi informasi sensitif dan mengurangi risiko terhadap keamanan informasi.', 3) on conflict (id) do update set title=excluded.title, content=excluded.content, sort_order=excluded.sort_order;
insert into public.document_sections (id, document_id, section_number, title, content, sort_order) values ('section-1-4', 'doc-st-002', '1.4', 'Ruang Lingkup', '1) Infrastruktur TI. 2) Sistem informasi/aplikasi. 3) Data dan informasi. 4) Keamanan informasi/siber. 5) Kompetensi sumber daya manusia yang menggunakannya.', 4) on conflict (id) do update set title=excluded.title, content=excluded.content, sort_order=excluded.sort_order;
insert into public.document_sections (id, document_id, section_number, title, content, sort_order) values ('section-2', 'doc-st-002', '2', 'Ketentuan Pelaksanaan', '1) Menjadi pedoman bagi seluruh pegawai Pusat Data dan Sarana Informatika (PDSI), serta dapat digunakan sebagai acuan standardisasi TI di lingkungan Kementerian Komunikasi dan Digital. 2) Berlaku sejak tanggal ditetapkan hingga digantikan dengan standardisasi baru. 3) Ditinjau ulang selambatnya satu tahun sejak ditetapkan dan diberlakukan. 4) Tetap berlaku otomatis pada periode yang sama jika tidak terdapat perubahan berdasarkan hasil peninjauan ulang.', 5) on conflict (id) do update set title=excluded.title, content=excluded.content, sort_order=excluded.sort_order;
insert into public.document_sections (id, document_id, section_number, title, content, sort_order) values ('section-3', 'doc-st-002', '3', 'Standardisasi Teknologi Informasi', 'Mencakup tujuh hal: Pusat Data/DC dan DRC; pembangunan dan pengembangan aplikasi; perangkat end device; perangkat keras komunikasi; pengamanan informasi; pengelolaan data; dan kompetensi sumber daya manusia.', 6) on conflict (id) do update set title=excluded.title, content=excluded.content, sort_order=excluded.sort_order;
insert into public.document_sections (id, document_id, section_number, title, content, sort_order) values ('section-4', 'doc-st-002', '4', 'Lampiran', 'Tidak ada.', 7) on conflict (id) do update set title=excluded.title, content=excluded.content, sort_order=excluded.sort_order;
insert into public.document_sections (id, document_id, section_number, title, content, sort_order) values ('section-1-5', 'doc-st-002', '1.5', 'Referensi', '1. Keputusan Menteri Komunikasi dan Informatika Nomor 320 Tahun 2023 tentang Pedoman Tata Kelola SPBE - Ketentuan Umum; Kebijakan Internal Sistem Pemerintahan Berbasis Elektronik
insert into public.document_sections (id, document_id, section_number, title, content, sort_order) values ('section-1-6', 'doc-st-002', '1.6', 'Istilah dan Definisi/Pengertian Umum', '1. Integrasi: Proses menghubungkan antar teknologi untuk menyederhanakan dan mengotomatisasi proses bisnis.
